#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define N (40960000)
static uint8_t *src, *dst;
static int nthreads;

static void* worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / nthreads;
    size_t start = id * chunk;
    size_t len = (id == nthreads-1) ? (N - start) : chunk;
